def parse_percent(text):
    """Parse '45%', '45', ' 7.5 % ' to fraction. Return None for invalid input."""
    if text is None or text == '':
        return None

    # Strip whitespace and remove % sign
    stripped = text.strip()
    if stripped.endswith('%'):
        stripped = stripped[:-1].strip()

    if stripped == '':
        return None

    try:
        value = float(stripped)
    except ValueError:
        return None

    # If original had %, divide by 100; otherwise treat as already a fraction? 
    # Wait: '45' -> 0.45, '45%' -> 0.45. So both are treated as percentages.
    # '7.5 %' -> 0.075. So all inputs are percentages.
    return value / 100.0
```

