def parse_version(text):
    """Parse a version string into a 3-tuple of integers.

    '1.2.3' -> (1, 2, 3)
    'v1.2' -> (1, 2, 0)
    '2' -> (2, 0, 0)

    Leading 'v' and surrounding spaces are allowed.
    Returns None for None, '', or malformed input like '1.x' or '1.2.3.4'.
    """
    if text is None:
        return None

    text = text.strip()
    if not text:
        return None

    # Remove leading 'v' if present
    if text.startswith('v'):
        text = text[1:]

    if not text:
        return None

    parts = text.split('.')

    # Must have 1 to 3 parts
    if len(parts) < 1 or len(parts) > 3:
        return None

    result = []
    for part in parts:
        if not part:
            return None
        try:
            result.append(int(part))
        except ValueError:
            return None

    # Pad with zeros to make it a 3-tuple
    while len(result) < 3:
        result.append(0)

    return tuple(result)
```

