    if not text:
        return None

    parts = text.split('.')

    # Must have 1 to 3 parts
    if len(parts) < 1 or len(parts) > 3:
        return None

    # All parts must be valid integers
    result = []
    for part in parts:
        if not part:
            return None
        try:
            result.append(int(part))
        except ValueError:
