def merge_files(paths, out):
    """Concatenate text files into out."""
    with open(out, "w", encoding="utf-8") as w:
        for p in paths:
            with open(p, encoding="utf-8") as f:
                content = f.read()
                if content:
                    if not content.endswith("\n"):
                        content += "\n"
                    w.write(content)
